import React, { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { ethers } from 'ethers';
import { Web3Context } from '../contexts/Web3Context';
import { useNavigate } from 'react-router-dom'; // Dùng để chuyển trang làm bài

const Marketplace = () => {
  const [exercises, setExercises] = useState([]);
  const { currentAccount } = useContext(Web3Context);
  const navigate = useNavigate();

  useEffect(() => {
    // API này giờ chỉ trả về Title, không có Question
    axios.get('http://localhost:5000/api/exercises').then(res => setExercises(res.data));
  }, []);

  const handleBuy = async (ex) => {
    if (!currentAccount) return alert("Kết nối ví đi!");

    try {
        // 1. Thanh toán tiền mua bài cho Creator
        const provider = new ethers.BrowserProvider(window.ethereum);
        const signer = await provider.getSigner();
        const price = ethers.parseEther(ex.price.toString());

        const tx = await signer.sendTransaction({
            to: ex.creator_address,
            value: price
        });
        await tx.wait();

        // 2. Lưu log
        await axios.post('http://localhost:5000/api/transaction/log', {
            user_address: currentAccount,
            type: 'BUY_EXERCISE',
            amount: -ex.price,
            tx_hash: tx.hash,
            description: `Mua bài thi: ${ex.title}`
        });

        alert("Mua thành công! Chuyển đến bài thi...");
        
        // 3. Chuyển sang trang làm bài (Truyền ID bài thi)
        // Bạn cần tạo thêm trang DoingTest.jsx để fetch nội dung full về
        navigate(`/test/${ex._id}`); 

    } catch (err) {
        alert("Lỗi: " + err.message);
    }
  };

  return (
    <div className="py-10 max-w-6xl mx-auto px-4">
      <h1 className="text-4xl font-bold text-white text-center mb-10">🛒 Cửa Hàng Đề Thi</h1>
      
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {exercises.map(ex => (
          <div key={ex._id} className="glass-panel p-6 flex flex-col justify-between hover:-translate-y-2 transition duration-300">
            <div>
                <span className="bg-blue-600/20 text-blue-300 text-xs px-2 py-1 rounded uppercase font-bold">{ex.topic}</span>
                <h3 className="text-xl font-bold text-white mt-3 mb-2">{ex.title}</h3>
                <p className="text-gray-400 text-sm">Người tạo: {ex.creator_address.slice(0,6)}...</p>
            </div>
            
            <div className="mt-6 pt-4 border-t border-white/10 flex items-center justify-between">
                <span className="text-emerald-400 font-bold font-mono">{ex.price} ETH</span>
                <button 
                    onClick={() => handleBuy(ex)}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-bold transition"
                >
                    Mua Ngay
                </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Marketplace;
